    def env(self, elapsed=60.0, **extra):
        e = {
            "PATH": os.path.join(self.venv, "bin") + os.pathsep + "/usr/bin:/bin",
            "HOME": self.root,
            "TMPDIR": os.path.join(self.root, "tmp"),
